export interface MinimIconProps
  extends Omit<React.ComponentPropsWithoutRef<"svg">, "children"> {
  name: IconName
  variant?: IconVariant
  title?: string
}

export const MinimIcon = React.forwardRef<SVGSVGElement, MinimIconProps>(
  function MinimIcon(
    { name, variant = "default", title, width = "1em", height = "1em", ...props },
    ref
  ) {
    const icon = icons[name]

    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        viewBox={icon.viewBox}
        width={width}
        height={height}
        fill="currentColor"
        role={title ? "img" : undefined}
        aria-hidden={title ? undefined : true}
        focusable="false"
        {...props}
      >
        {title ? <title>{title}</title> : null}
        <g dangerouslySetInnerHTML={{ __html: icon[variant] }} />
      </svg>
    )
  }
)
